try{$q=$db->prepare("SELECT appointment_date,appointment_time,status FROM counseling_appointments WHERE user_id=? AND status IN ('pending','confirmed','in_progress','rescheduled','follow_up_scheduled') AND appointment_date>=? ORDER BY appointment_date,appointment_time,id LIMIT 1");$q->execute([$uid,(new DateTimeImmutable('today',new DateTimeZone('Asia/Manila')))->format('Y-m-d')]);$sdNext=$q->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable $e){$sdAppointmentKnown=false;}
try{$q=$db->query("SELECT setting_key,setting_value FROM system_settings WHERE setting_key IN ('pds_enabled','counseling_enabled')");foreach($q->fetchAll(PDO::FETCH_ASSOC) as $setting)$sdServices[$setting['setting_key']]=$setting['setting_value']==='1';}catch(Throwable $e){}
$sdPdsLabel=!$sdPdsKnown?'Status unavailable':($sdPds?'Saved':'Not started');$sdSurveyLabel=!$sdEligible?'Not applicable':(!$sdSurveyKnown?'Status unavailable':($sdSurvey?'Results available · '.$sdSurveyYear:($sdSurveyYear!==''?'Ready for '.$sdSurveyYear:'PDS school year needed')));
$sdFullName=trim(implode(' ',array_filter([$user_info['first_name']??'',$user_info['middle_name']??'',$user_info['last_name']??''])));
$sdInitials=mb_strtoupper(mb_substr($user_info['first_name']??'S',0,1).mb_substr($user_info['last_name']??'',0,1));
$sdStatusLabels=['pending'=>'Awaiting confirmation','confirmed'=>'Confirmed','in_progress'=>'In progress','rescheduled'=>'Rescheduled','follow_up_scheduled'=>'Follow-up scheduled'];
